add_action( 'woocommerce_cart_calculate_fees', 'perfectpixel_discount_cheapest_item' );

function perfectpixel_discount_cheapest_item( $cart ) {
	if ( is_admin() && ! defined( 'DOING_AJAX' ) ) {
		return;
	}
	if ( $cart->get_cart_contents_count() < max( 1, (int) '{{cheapest_min_items}}' ) ) {
		return;
	}
	$cheapest = null;
	foreach ( $cart->get_cart() as $item ) {
		if ( $item['quantity'] < 1 ) {
			continue;
		}
		$unit = $item['line_subtotal'] / $item['quantity'];
		if ( null === $cheapest || $unit < $cheapest ) {
			$cheapest = $unit;
		}
	}
	$discount = (float) $cheapest * min( 100, max( 0, (float) '{{cheapest_percent}}' ) ) / 100;
	if ( $discount > 0 ) {
		$cart->add_fee( '{{cheapest_label}}', -$discount, true );
	}
}
